(7758913, 1284484, 38162, '<td valign="top">A bit heavy on the saturation for me. Good composition. GL.</td>', 'A bit heavy on the saturation for me. Good composition. GL.', '2023-10-15 19:24:54.000000', NULL, 1),
(7758959, 1284501, 83313, '<td valign="top">I love the patterns left by the waves.</td>', 'I love the patterns left by the waves.', '2023-10-16 16:48:39.000000', NULL, 1),
(7758960, 1284496, 83313, '<td valign="top">I like the scene, but I think it needs some separation between subject and bckground. All that business in the back keeps drawing my eye away from the subject. Some OOF blur, or maybe softening and desaturating the background slightly could do it.</td>', 'I like the scene, but I think it needs some separation between subject and bckground. All that business in the back keeps drawing my eye away from the subject. Some OOF blur, or maybe softening and desaturating the background slightly could do it.', '2023-10-16 16:51:04.000000', NULL, 1),
