(7759009, 1284501, 16148, '<td valign="top">Congrats on the blue!  Love the stutter step prints, from the left paw, top right.  Nicely framed - paying attention to the edges.  Do you think the white toenail on the drift wood should be removed?  It demands a lot of attention in this full frame composition.</td>', 'Congrats on the blue!  Love the stutter step prints, from the left paw, top right.  Nicely framed - paying attention to the edges.  Do you think the white toenail on the drift wood should be removed?  It demands a lot of attention in this full frame composition.', '2023-10-18 09:36:03.000000', NULL, 0),
(7759010, 1284482, 16148, '<td valign="top">Beautiful autumn capture of this tiny underwater world. Sunken fruit on the floor, sailing leaves above, lotus leaf islands join hands, circling goldfish, and a flower of hope.  A much larger story here for the curious.</td>', 'Beautiful autumn capture of this tiny underwater world. Sunken fruit on the floor, sailing leaves above, lotus leaf islands join hands, circling goldfish, and a flower of hope.  A much larger story here for the curious.', '2023-10-18 09:46:05.000000', NULL, 0),
